cat <<EOF > /root/parse_trivy.py
import json
import csv

input_file = '/root/trivy_output.json'
output_file = '/root/security_audit.csv'

try:
    with open(input_file, 'r') as f:
        data = json.load(f)

    with open(output_file, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url'])

        if 'Results' in data:
            for result in data['Results']:
                if 'Vulnerabilities' in result:
                    for vuln in result['Vulnerabilities']:
                        package = vuln.get('PkgName', 'N/A')
                        version = vuln.get('InstalledVersion', 'N/A')
                        cve_id = vuln.get('VulnerabilityID', 'N/A')
                        severity = vuln.get('Severity', 'N/A')

                        # CVSS Score extraction logic
                        cvss_score = 'N/A'
                        cvss = vuln.get('CVSS', {})
                        if cvss:
                            # Priority: nvd > ghsa > redhat
                            sources = ['nvd', 'ghsa', 'redhat']
                            for source in sources:
                                if source in cvss:
                                    if 'V3Score' in cvss[source]:
                                        cvss_score = cvss[source]['V3Score']
                                        break
                                    elif 'V2Score' in cvss[source]:
                                        cvss_score = cvss[source]['V2Score']
                                        break

                        fixed_version = vuln.get('FixedVersion', 'N/A')
                        # Prefer Title, fallback to Description (truncated if too long to keep it readable, though CSV handles newlines)
                        title = vuln.get('Title', '')
                        if not title:
                            title = vuln.get('Description', 'N/A')

                        # Clean up title/description to remove newlines for cleaner CSV
                        title = title.replace('\n', ' ').strip()

                        url = vuln.get('PrimaryURL', '')
                        if not url and 'References' in vuln and vuln['References']:
                             url = vuln['References'][0]
                        if not url:
                            url = 'N/A'

                        writer.writerow([package, version, cve_id, severity, cvss_score, fixed_version, title, url])
    print("CSV generation complete.")
except Exception as e:
    print(f"Error: {e}")
EOF
